27	/// Tela 4 — Meus Registros, spec-4-1's real build: every `Entry`,
28	/// newest-first, grouped by day, each card marked by origin. Replaces the
29	/// former `MeusRegistrosPlaceholderScreen`.
30	///
31	/// [cubit] is a DI `lazySingleton` (Code Map) — this `StatefulWidget` never
32	/// closes it (`BlocProvider.value`, same convention
33	/// `AccountSettingsScreen` already uses for its own singleton cubit); only
34	/// this screen's own [ScrollController] is this `State`'s to dispose.
35	///
36	/// The global `ExpiryOverlayHost` shows its "Sessão expirada" dialog via
37	/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
38	/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
39	/// rebuilt from scratch underneath it, so [_scrollController]'s position
40	/// and [cubit]'s state survive that overlay appearing with no extra code
41	/// needed here (Acceptance Criteria's third bullet).
42	class MeusRegistrosScreen extends StatefulWidget {
43	  const MeusRegistrosScreen({
44	    required this.cubit,
45	    required this.searchCubit,
46	    super.key,
47	  });
48	
49	  final MeusRegistrosCubit cubit;
50	
51	  /// spec-5-1 — the permanently-docked `EntriesSearchBar`'s own cubit, a DI
52	  /// `lazySingleton` like [cubit] (Code Map); this `StatefulWidget` never
53	  /// closes it either, same rationale [cubit]'s own doc above gives.
54	  final EntriesSearchCubit searchCubit;
55	
56	  @override
57	  State<MeusRegistrosScreen> createState() => _MeusRegistrosScreenState();
58	}
59	
60	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
61	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
62	  // `BootSplashScreen`.
63	  static const _skeletonThreshold = Duration(milliseconds: 300);
64	
65	  final ScrollController _scrollController = ScrollController();
66	  Timer? _skeletonTimer;
67	  bool _showSkeleton = false;
68	
69	  /// spec-5-1 — the search surface's own 300ms skeleton threshold,
