        final gate = Completer<void>();
        addTearDown(() {
          if (!gate.isCompleted) {
            gate.complete();
          }
        });
        final fakeRepository = _FakeEntriesRepository()
          ..queueList(right(const EntriesPage(items: [], nextCursor: null)))
          ..queueList(right(const EntriesPage(items: [], nextCursor: null)))
          ..searchGate = gate
          ..queueSearch(right([_entry('search-1', '2026-01-01T10:00:00')]));

